<script setup>
import {computed,onMounted,ref} from 'vue';import {get,fmt,pct} from '../api/client';import MetricCard from '../components/MetricCard.vue';import DataTable from '../components/DataTable.vue';
const data=ref(null),error=ref(''),activeModel=ref('multi_factor_rank'),showBacktestHelp=ref(false),today=new Date().toLocaleDateString('en-CA');const modelNames={multi_factor_rank:'次日方向模型',tradeable_t1_open:'T+1可交易模型'};const model=computed(()=>data.value?.models?.[activeModel.value]||{latest_prediction:{},latest_intraday_groups:[],latest_verification:{},latest_verification_groups:[]}),intradayAt=computed(()=>model.value.latest_intraday_groups?.[0]?.observed_at||''),intradayIsToday=computed(()=>String(intradayAt.value).slice(0,10)===today);onMounted(async()=>{try{data.value=await get('/dashboard')}catch(e){error.value=e.message}});
const cols=[{label:'分组',key:'top_n',format:v=>`Top${v}`},{label:'上涨比例',key:'up_rate',format:pct},{label:'平均收益',key:'avg_return',format:pct,class:v=>v>0?'positive':'negative'},{label:'市场收益',key:'market_avg_return',format:pct},{label:'超额收益',key:'excess_return',format:pct,class:v=>v>0?'positive':'negative'}];
</script><template><div v-if="error" class="empty">{{error}}</div><div v-else-if="!data" class="empty">加载中…</div><template v-else><div class="grid"><MetricCard label="股票数量" :value="fmt(data.stats.stock_count,0)" sub="SH · SZ · BJ"/><MetricCard label="日线记录" :value="fmt(data.stats.daily_count,0)" :sub="`${data.stats.first_date} — ${data.stats.latest_date}`"/><MetricCard label="预测批次" :value="data.stats.prediction_runs" sub="两套模型独立保存"/><MetricCard label="正式验证" :value="data.stats.verification_runs" sub="按模型分别验证"/></div><div class="model-tabs"><button v-for="(name,code) in modelNames" :class="{active:activeModel===code}" @click="activeModel=code">{{name}}</button></div><div class="model-scope-note">当前查看：<b>{{modelNames[activeModel]}}</b> · <template v-if="activeModel==='tradeable_t1_open'">下一交易日开盘买入，再下一交易日开盘卖出</template><template v-else>信号日收盘至下一交易日收盘</template></div><div class="section"><div class="detail-heading"><div><h2>历史回测表现</h2><span class="backtest-caption">历史样本估算 · 随每日预测更新 · 不是正式验证结果</span></div><button @click="showBacktestHelp=!showBacktestHelp">{{showBacktestHelp?'收起说明':'指标说明'}}</button></div><div v-if="showBacktestHelp" class="card logic-card backtest-help"><p><b>样本上涨率：</b>历史候选收益为正的比例；<b>候选平均：</b>候选平均收益；<b>市场平均：</b>同口径全市场平均收益；<b>样本超额：</b>候选平均减市场平均。</p><p>历史较短时可能偏乐观，真实发布结果请看下方“最新正式验证”。</p></div><div class="grid backtest-grid"><MetricCard label="样本上涨率" :value="pct(model.latest_prediction.backtest_up_rate)"/><MetricCard label="候选平均" :value="pct(model.latest_prediction.backtest_avg_return)"/><MetricCard label="市场平均" :value="pct(model.latest_prediction.market_avg_return)"/><MetricCard label="样本超额" :value="pct(model.latest_prediction.excess_return)"/></div></div><div class="section"><div class="section-heading"><div><h2>最新盘中表现</h2><span>盘中临时快照 · 不随每日收盘流水线更新</span></div><span v-if="intradayAt" :class="intradayIsToday?'snapshot-current':'snapshot-stale'">{{intradayIsToday?'今日快照':'历史快照'}} · {{intradayAt}}</span></div><p v-if="intradayAt&&!intradayIsToday" class="snapshot-warning">当前展示的不是今日盘中数据，仅供历史参考；请执行“获取盘中观察”生成最新快照。</p><p v-else-if="intradayAt" class="hint">盘中价格仍会变化，最终结果以正式验证为准。</p><DataTable :columns="cols" :rows="model.latest_intraday_groups"/></div><div class="section"><div class="section-heading"><div><h2>最新正式验证</h2><span>已发布候选的真实后续行情 · 随每日收盘流水线更新</span></div><span v-if="model.latest_verification?.actual_trade_date" class="snapshot-current">信号日 {{model.latest_verification.base_date}} · 验证日 {{model.latest_verification.actual_trade_date}}</span></div><p v-if="model.latest_verification?.actual_trade_date" class="hint">正式结果按当前模型收益口径计算；未计交易成本、滑点及无法成交影响。</p><DataTable :columns="cols" :rows="model.latest_verification_groups"/></div></template></template>
